solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const succ = Array.from({ length: n }, () => []);
const indeg = new Array(n).fill(0);
let pos = 2;
for (let i = 0; i < m; i++) {
  const u = tok[pos] - 1, v = tok[pos + 1] - 1;
  pos += 2;
  succ[u].push(v);
  indeg[v]++;
}
const order = [];
const queue = [];
for (let v = 0; v < n; v++) if (indeg[v] === 0) queue.push(v);
for (let h = 0; h < queue.length; h++) {
  const u = queue[h];
  order.push(u);
  for (const v of succ[u]) { indeg[v]--; if (indeg[v] === 0) queue.push(v); }
}
const grundy = new Array(n).fill(0);
for (let i = order.length - 1; i >= 0; i--) {
  const u = order[i];
  const seen = new Set();
  for (const v of succ[u]) seen.add(grundy[v]);
  let g = 0;
  while (seen.has(g)) g++;
  grundy[u] = g;
}
const q = tok[pos++];
const out = [];
for (let i = 0; i < q; i++) {
  const t = tok[pos];
  let x = 0;
  for (let j = 0; j < t; j++) x ^= grundy[tok[pos + 1 + j] - 1];
  pos += 1 + t;
  out.push(x !== 0 ? "First" : "Second");
}
console.log(out.join("\n"));

