import java.io.*;
import java.util.*;

public class Main {
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        ArrayList<Integer>[] succ = new ArrayList[n];
        for (int i = 0; i < n; i++) succ[i] = new ArrayList<>();
        int[] indeg = new int[n];
        for (int i = 0; i < m; i++) {
            in.nextToken(); int u = (int) in.nval - 1;
            in.nextToken(); int v = (int) in.nval - 1;
            succ[u].add(v);
            indeg[v]++;
        }
        int[] order = new int[n];
        int cnt = 0;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int v = 0; v < n; v++) if (indeg[v] == 0) queue.add(v);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            order[cnt++] = u;
            for (int v : succ[u]) if (--indeg[v] == 0) queue.add(v);
        }
        int[] grundy = new int[n];
        for (int i = cnt - 1; i >= 0; i--) {
            int u = order[i];
            HashSet<Integer> seen = new HashSet<>();
            for (int v : succ[u]) seen.add(grundy[v]);
            int g = 0;
            while (seen.contains(g)) g++;
            grundy[u] = g;
        }
        in.nextToken();
        int q = (int) in.nval;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int t = (int) in.nval;
            int x = 0;
            for (int j = 0; j < t; j++) {
                in.nextToken();
                x ^= grundy[(int) in.nval - 1];
            }
            out.append(x != 0 ? "First" : "Second").append('\n');
        }
        System.out.print(out);
    }
}

