#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    vector<vector<int>> succ(n);
    vector<int> indeg(n, 0);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        succ[u - 1].push_back(v - 1);
        indeg[v - 1]++;
    }
    vector<int> order;
    queue<int> q;
    for (int v = 0; v < n; v++) if (indeg[v] == 0) q.push(v);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : succ[u]) if (--indeg[v] == 0) q.push(v);
    }
    vector<int> grundy(n, 0);
    for (int i = (int)order.size() - 1; i >= 0; i--) {
        int u = order[i];
        set<int> seen;
        for (int v : succ[u]) seen.insert(grundy[v]);
        int g = 0;
        while (seen.count(g)) g++;
        grundy[u] = g;
    }
    int queries;
    scanf("%d", &queries);
    while (queries--) {
        int t, x = 0;
        scanf("%d", &t);
        while (t--) {
            int v;
            scanf("%d", &v);
            x ^= grundy[v - 1];
        }
        puts(x != 0 ? "First" : "Second");
    }
    return 0;
}
